import{_ as i,a as e,b as o,c as r,d as t,e as l,f as n,g as s,h as c,i as d,j as p,k as m}from"./chunks/101-10.abiX99wn.js";import{_ as u,o as g,c as b,a3 as h}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"Basi della calibrazione","description":"","frontmatter":{"source_hash":"2ab418e8fa","source_commit":"7a18e7c"},"headers":[],"relativePath":"it/calibrate/101.md","filePath":"it/calibrate/101.md"}'),z={name:"it/calibrate/101.md"};function f(v,a,_,q,x,k){return g(),b("div",null,[...a[0]||(a[0]=[h('<h3 id="about-calibration" tabindex="-1">La calibrazione <a class="header-anchor" href="#about-calibration" aria-label="Permalink to &quot;La calibrazione {#about-calibration}&quot;">​</a></h3><h4 id="how-do-sensors-work" tabindex="-1">Come funzionano i sensori? <a class="header-anchor" href="#how-do-sensors-work" aria-label="Permalink to &quot;Come funzionano i sensori? {#how-do-sensors-work}&quot;">​</a></h4><p>I sensori di glicemia generano un segnale elettrico tramite una reazione chimica con la concentrazione di glucosio nel liquido interstiziale: in xDrip lo chiamiamo di solito dato grezzo (raw).<br><strong>Questo valore non è direttamente utilizzabile come misura della glicemia.</strong></p><img src="'+i+'" style="zoom:75%;"><p>Esiste un &quot;<a href="https://pubmed.ncbi.nlm.nih.gov/20920428/" target="_blank" rel="noreferrer">ritardo</a>&quot; fisiologico tra la glicemia capillare e la concentrazione di glucosio interstiziale, che tendono a diventare proporzionali dopo un certo tempo. Consideriamo che 10 minuti con <strong>glicemia stabile</strong> siano un tempo ragionevole per ridurre l&#39;imprecisione.</p><img src="'+e+'" style="zoom:75%;"><p>Per usare i dati grezzi come equivalente della glicemia devi fornire loro un riferimento. A meno che il sensore non abbia un calcolo di calibrazione nativo (detto anche calibrazione di fabbrica), i dati grezzi <strong><a href="https://www.liebertpub.com/doi/10.1089/dia.2016.0112" target="_blank" rel="noreferrer">non</a></strong> corrisponderanno alla glicemia reale.</p><br><h4 id="proprietary-calibration-algorithms" tabindex="-1">Algoritmi di calibrazione proprietari <a class="header-anchor" href="#proprietary-calibration-algorithms" aria-label="Permalink to &quot;Algoritmi di calibrazione proprietari {#proprietary-calibration-algorithms}&quot;">​</a></h4><p>Alcuni produttori forniscono sensori calibrati in fabbrica (G6 e Libre) che possono non raggiungere la precisione attesa. Mentre il primo permette di applicare la calibrazione in modalità nativa, il secondo non può essere calibrato con l&#39;app del produttore.</p><br><h4 id="native-mode-calibration" tabindex="-1">Calibrazione in modalità nativa <a class="header-anchor" href="#native-mode-calibration" aria-label="Permalink to &quot;Calibrazione in modalità nativa {#native-mode-calibration}&quot;">​</a></h4><p>I sensori G6, G7, 1, 1+ e Stelo sono calibrati in fabbrica: all&#39;avvio inserirai il codice di calibrazione o il codice del sensore. Se vuoi calibrare, xDrip si limiterà a inviare i dati di calibrazione al trasmettitore del sensore perché li elabori: non applicherà alcun algoritmo locale. In modalità nativa xDrip si basa sui dati del trasmettitore: per questo il tuo ricevitore (se ne hai uno) mostrerà gli stessi dati.</p><p>Maggiori informazioni <a href="https://navid200.github.io/xDrip/docs/Calibrate-G6.html" target="_blank" rel="noreferrer">qui</a>.</p><br><h3 id="when-calibrating-is-dangerous" tabindex="-1">Quando calibrare è pericoloso <a class="header-anchor" href="#when-calibrating-is-dangerous" aria-label="Permalink to &quot;Quando calibrare è pericoloso {#when-calibrating-is-dangerous}&quot;">​</a></h3><p>Calibrare quando la glicemia non è stabile genera calibrazioni sbagliate e quindi valori di glicemia errati su cui non puoi fare affidamento.<br> Calibrare quando la curva della glicemia è piatta è estremamente pericoloso, perché significa che il sensore è fuori intervallo o non funziona correttamente, e i dati grezzi non rappresentano affatto la glicemia.</p><img src="'+o+'" style="zoom:75%;"><img src="'+r+'" style="zoom:75%;"><br><h3 id="xdrip-calibration-algorithm" tabindex="-1">L&#39;algoritmo di calibrazione di xDrip <a class="header-anchor" href="#xdrip-calibration-algorithm" aria-label="Permalink to &quot;L&#39;algoritmo di calibrazione di xDrip {#xdrip-calibration-algorithm}&quot;">​</a></h3><h4 id="intercept" tabindex="-1">Intercetta <a class="header-anchor" href="#intercept" aria-label="Permalink to &quot;Intercetta {#intercept}&quot;">​</a></h4><p>Se misuri la glicemia con un glucometro, che indica 100 mg/dl stabile, e 10 minuti dopo il CGM legge 130, vorrai calibrare. È così che dici a xDrip che un valore grezzo di 130 corrisponde a un valore reale di 100.</p><p>Calibrando in queste condizioni otterrai un grafico di calibrazione che, in teoria, appare così:</p><img src="'+t+'" style="zoom:75%;"><p>Che si traduce in: la glicemia calibrata sarà il valore grezzo meno 30.</p><p>-30 è detta <strong>intercetta</strong>, cioè uno <strong>scostamento</strong> (offset) tra il valore grezzo e la glicemia calibrata.<br> L&#39;intercetta pesa di più sulle misure di glicemia basse: è consigliabile che sia il più precisa possibile, perché xDrip sia preciso nell&#39;intervallo basso, quello che conta per la tua sicurezza.</p><p><strong>Esegui la prima calibrazione del sensore con glicemia stabile nella parte bassa dell&#39;intervallo normale (da 90 a 120 mg/dl, da 5 a 7 mmol/l)</strong>.</p><p>Il valore dell&#39;intercetta sposta la glicemia calibrata verso l&#39;alto o verso il basso.</p><img src="'+l+'" style="zoom:75%;"><br><h4 id="slope" tabindex="-1">Pendenza <a class="header-anchor" href="#slope" aria-label="Permalink to &quot;Pendenza {#slope}&quot;">​</a></h4><p>Con la calibrazione qui sopra, le letture potrebbero essere imprecise quando il valore grezzo è molto diverso... ad esempio xDrip mostra 170 mg/dl e il glucometro 205 mg/dl. In questo caso lo scostamento è diverso con la glicemia più alta... è il valore grezzo più 5...</p><img src="'+n+'" style="zoom:75%;"><p>Per rendere xDrip preciso in questo intervallo di glicemia, devi aggiungere un altro punto di calibrazione. Fatto questo, la curva cambierà in teoria così:</p><img src="'+s+'" style="zoom:75%;"><p>Come vedi, la linea rossa è più ripida e il parametro della pendenza è aumentato. In questo caso, una pendenza di 1,5 significa che una variazione più piccola del valore grezzo produrrà una variazione più grande della glicemia mostrata da xDrip.<br> La pendenza pesa di più sulle misure di glicemia alte: se ti serve precisione sui valori alti, aggiungi un punto di calibrazione nell&#39;intervallo alto.</p><p><strong>Aggiungi un valore di calibrazione più alto, con glicemia stabile nella parte alta dell&#39;intervallo normale; non usare una glicemia troppo alta per calibrare (da 180 a 220 mg/dl, da 10 a 12 mmol/l).</strong></p><p>Questa <strong>pendenza</strong> (slope) è un coefficiente che <strong>moltiplica</strong> il valore grezzo, simile a un <strong>guadagno</strong>. Aumenta o diminuisce la sensibilità della glicemia ai dati grezzi.</p><img src="'+c+'" style="zoom:75%;"><br><h4 id="maths-models-and-real-life" tabindex="-1">Matematica, modelli e vita reale <a class="header-anchor" href="#maths-models-and-real-life" aria-label="Permalink to &quot;Matematica, modelli e vita reale {#maths-models-and-real-life}&quot;">​</a></h4><p>La curva di calibrazione è il risultato di un calcolo matematico che cerca la retta che meglio si adatta a tutti i punti di calibrazione forniti, minimizzando la distanza tra ogni punto e la retta teorica.</p><img src="'+d+'" style="zoom:75%;"><p>La sua qualità dipende dal sensore e dalla tua strategia di calibrazione.<br> Se il sensore è rumoroso o non calibri con glicemia stabile, l&#39;algoritmo avrà difficoltà ad adattarsi a tutti i dati e ne risulterà una curva di calibrazione imprecisa: non puoi far passare una retta vicino a tutti i punti di una nuvola di calibrazioni.</p><img src="'+p+'" style="zoom:75%;"><br><h4 id="interstitial-delay" tabindex="-1">Il &quot;ritardo&quot; interstiziale <a class="header-anchor" href="#interstitial-delay" aria-label="Permalink to &quot;Il &quot;ritardo&quot; interstiziale {#interstitial-delay}&quot;">​</a></h4><p>È probabilmente il fattore più complesso da considerare quando si calibra: per questo una glicemia stabile è fondamentale.</p><p>C&#39;è un ritardo tra la glicemia capillare e la concentrazione di glucosio nel liquido interstiziale, e ci sono anche altri fattori che la fanno evolvere in modo diverso, come l&#39;attività fisica, ...</p><p>Poiché xDrip non può conoscere né indovinare questo ritardo, calibrare con una glicemia che cambia rapidamente non funziona.</p><img src="'+m+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 7/12/2024</em></a></p>',54)])])}const D=u(z,[["render",f]]);export{C as __pageData,D as default};
